package com.hrm.gui;import com.hrm.model.Payroll;import com.hrm.service.PayrollService;import javax.swing.*;import java.awt.*;import java.util.*;public class MyPayslipPanel extends JPanel{private final JTable t=Ui.table(new String[]{"Mã NV","Nhân viên","Tháng","Năm","Lương CB","OT","Thưởng","Khấu trừ","Thực lĩnh","Trạng thái"});private final JComboBox<String> y=new JComboBox<>(new String[]{"Tất cả 5 năm","2022","2023","2024","2025","2026"});private final int emp;public MyPayslipPanel(Integer emp){this.emp=emp;setLayout(new BorderLayout(8,8));add(Ui.top("Phiếu lương của tôi - chỉ phiếu HR đã gửi"),BorderLayout.NORTH);JPanel b=new JPanel(new FlowLayout(FlowLayout.LEFT));b.add(new JLabel("Năm:"));b.add(y);add(b,BorderLayout.SOUTH);add(new JScrollPane(t),BorderLayout.CENTER);y.addActionListener(e->load());load();}private int yearValue(){String v=(String)y.getSelectedItem();return "Tất cả 5 năm".equals(v)?0:Integer.parseInt(v);}private void load(){try{var rows=new ArrayList<String[]>();for(Payroll p:new PayrollService().mine(emp,yearValue()))rows.add(new String[]{p.employeeCode(),p.employeeName(),String.valueOf(p.month()),String.valueOf(p.year()),fmt(p.base()),fmt(p.overtime()),fmt(p.bonus()),fmt(p.deduction()),fmt(p.net()),p.status()});Ui.fill(t,rows);}catch(Exception e){Ui.error(this,e);}}private String fmt(double d){return String.format("%,.0f",d);}}
